Func<object[], object[], object[]> Handle = (args, result) =>
{
    if (args is null || result is null || args.Length < 2) { return result; }

    var unit = args[0] as Orc.Game.Cards.UnitCard;
    var host = args[args.Length - 1] as Orc.Game.Cards.UnitCard;
    if (!object.ReferenceEquals(unit, host)) { return result; }

    // 固守：不能执行指挥移动（含撤退）。
    return new object[] { Orc.Game.Judicators.LegEligibilityFailure.FlagFalse };
};

Func<object[], object[], object[]> Handle = (args, result) =>
{
    if (args is null || result is null || args.Length < 1) { return result; }

    var target = args[0] as Orc.Game.Cards.UnitCard;
    var host = args[args.Length - 1] as Orc.Game.Cards.UnitCard;
    if (!object.ReferenceEquals(target, host)) { return result; }

    // 固守：不可被抑制。
    return new object[] { Orc.Game.Judicators.InhibitEligibilityFailure.Immune };
};
